css:
&.slide.tpl {
& { padding:58px 80px 84px; display:flex; flex-direction:column; gap:22px; }
header { flex:none; display:flex; align-items:baseline; gap:28px; flex-wrap:wrap; }
header p { order:2; color:var(--accent); font:600 21px/1 var(--font-mono,var(--mono)); letter-spacing:.14em; text-transform:uppercase; margin:0; padding:10px 16px; border:1.5px solid color-mix(in srgb,var(--accent) 55%,transparent); border-radius:999px; }
header h2 { order:1; font-size:56px; line-height:1.08; margin:0; max-width:46ch; text-wrap:balance; }
header :empty { display:none; }
header:has(h2:empty):has(p:empty) { display:none; }
.rl-stage { --logg:660px; --term:color-mix(in srgb,var(--bg) 55%,var(--surface)); position:relative; flex:1; min-height:0; display:flex; flex-direction:column; justify-content:flex-end; padding:58px 0 22px calc(100% - var(--logg)); overflow:hidden; counter-reset:steg; }
.rl-term { position:absolute; top:0; right:0; bottom:0; width:var(--logg); border-radius:calc(var(--radius) * .6); background:var(--term); border:1px solid var(--line); }
.rl-term::before { content:""; position:absolute; left:0; right:0; top:0; height:46px; border-bottom:1px solid var(--line); background:var(--term); border-radius:calc(var(--radius) * .6) calc(var(--radius) * .6) 0 0; z-index:3; }
.rl-term i { position:absolute; top:17px; width:12px; height:12px; border-radius:50%; background:var(--line); z-index:4; }
.rl-term i:nth-child(1) { left:20px; background:var(--accent-2); } .rl-term i:nth-child(2) { left:40px; background:var(--muted); } .rl-term i:nth-child(3) { left:60px; background:var(--accent); }
.rl-stage::after { content:""; position:absolute; right:1px; top:47px; width:calc(var(--logg) - 2px); height:90px; background:linear-gradient(var(--term),transparent); z-index:2; pointer-events:none; }
.rl-stage figure { display:contents; }
.rl-stage img { position:absolute; left:0; top:0; width:calc(100% - var(--logg) - 40px); height:100%; object-fit:contain; visibility:hidden; opacity:0; transition:opacity .25s ease; }
.rib-base img, .image-step.in img, .image-step:not([data-step]) img { visibility:inherit; opacity:1; }
.rib-base:has(~.image-step.in) img, .rib-base:has(~.image-step:not([data-step])) img, .image-step:has(~.image-step.in) img, .image-step:not([data-step]):has(~.image-step) img { visibility:hidden; opacity:0; }
.rl-stage figcaption { position:relative; z-index:1; display:none; margin:0; padding:6px 22px 6px 21px; font:500 22px/1.42 var(--font-mono,var(--mono)); color:var(--muted); border-left:3px solid transparent; }
.image-step figcaption { counter-increment:steg; }
.rib-base figcaption { display:block; color:var(--accent); }
.rib-base figcaption span::before { content:"$ "; color:var(--muted); }
.rib-base figcaption:has(span:empty) { display:none; }
.image-step.in figcaption, .image-step:not([data-step]) figcaption { display:block; }
figcaption b { font-weight:600; color:inherit; margin-right:.5em; }
figcaption b::after { content:":"; }
.rl-fill { flex:1 1 0; min-height:0; }
.image-step figcaption b::before { content:counter(steg,decimal-leading-zero) " › "; color:var(--muted); font-weight:400; }
figcaption span mark { background:none; color:var(--accent-2); font-weight:700; }
.image-step.in:not(:has(~.image-step.in)) figcaption, .image-step:not([data-step]):last-child figcaption { color:var(--ink); background:color-mix(in srgb,var(--accent) 11%,transparent); border-left-color:var(--accent); }
.image-step.in:not(:has(~.image-step.in)) figcaption b, .image-step:not([data-step]):last-child figcaption b { color:var(--accent); }
.image-step.in:not(:has(~.image-step.in)) figcaption span::after, .image-step:not([data-step]):last-child figcaption span::after { content:"▋"; color:var(--accent); margin-left:.35em; }
&[data-body-motion="none"] * { transition:none!important; }
@media(prefers-reduced-motion:reduce) { & * { transition:none!important; } }
}
